bool VulkanMeshPipeline::bind(VkCommandBuffer cmd,const VulkanMeshBuffer& mesh,std::uint32_t count,const MeshFrameConstants& f,const MeshMaterialConstants& m){if(!is_initialized()||!cmd||!mesh.is_initialized()||!count)return false;void*p=nullptr;if(vkMapMemory(device_,frame_memory_,0,sizeof(f),0,&p)!=VK_SUCCESS)return false;std::memcpy(p,&f,sizeof(f));vkUnmapMemory(device_,frame_memory_);if(vkMapMemory(device_,material_memory_,0,sizeof(m),0,&p)!=VK_SUCCESS)return false;std::memcpy(p,&m,sizeof(m));vkUnmapMemory(device_,material_memory_);VkDescriptorBufferInfo i[2]={{frame_buffer_,0,sizeof(f)},{material_buffer_,0,sizeof(m)}};VkWriteDescriptorSet w[2]{};for(int n=0;n<2;++n){w[n].sType=VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;w[n].dstSet=set_;w[n].dstBinding=n;w[n].descriptorCount=1;w[n].descriptorType=VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;w[n].pBufferInfo=&i[n];}vkUpdateDescriptorSets(device_,2,w,0,nullptr);vkCmdBindPipeline(cmd,VK_PIPELINE_BIND_POINT_GRAPHICS,pipeline_);vkCmdBindDescriptorSets(cmd,VK_PIPELINE_BIND_POINT_GRAPHICS,pipeline_layout_,0,1,&set_,0,nullptr);VkDeviceSize off=0;VkBuffer vb=mesh.vertex_buffer();vkCmdBindVertexBuffers(cmd,0,1,&vb,&off);vkCmdBindIndexBuffer(cmd,mesh.index_buffer(),0,VK_INDEX_TYPE_UINT32);vkCmdDrawIndexed(cmd,count,1,0,0,0);return true;}
